package com.pandinila.broadband_management.service;
import com.pandinila.broadband_management.entity.*; import com.pandinila.broadband_management.entity.Enums.*; import com.pandinila.broadband_management.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class IncidentService { private final IncidentRepository repo; private final CustomerService customers; private final MonitoringService monitoring; private final SupportTeamRepository teams; private final EngineerRepository engineers;
 public IncidentService(IncidentRepository r,CustomerService c,MonitoringService m,SupportTeamRepository t,EngineerRepository e){repo=r;customers=c;monitoring=m;teams=t;engineers=e;} public List<Incident> all(){return repo.findAll();} public Incident one(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Incident not found: "+id));}
 @Transactional public Incident createProactive(Long customerId){Customer c=customers.one(customerId); ComplaintPrediction p=monitoring.latestPrediction(c).orElseThrow(()->new IllegalStateException("Analyze customer before creating an incident")); if(repo.existsByCustomerAndIncidentTypeAndStatusNotIn(c,IncidentType.PROACTIVE_NETWORK_ISSUE,List.of(IncidentStatus.RESOLVED,IncidentStatus.CLOSED))) throw new IllegalStateException("An active proactive incident already exists for this customer"); Incident i=new Incident();i.setIncidentNumber("INC"+(100000+repo.count()+1));i.setCustomer(c);i.setIncidentType(IncidentType.PROACTIVE_NETWORK_ISSUE);i.setRiskScore(p.getRiskScore());i.setQualityScore(monitoring.latestQuality(c).map(ServiceQuality::getQualityScore).orElse(0d));i.setPriority(p.getRiskScore()>=80?Priority.HIGH:p.getRiskScore()>=60?Priority.MEDIUM:Priority.LOW);i.setSeverity(i.getPriority().name());i.setDescription("Proactive service assurance: "+p.getReasons()); return repo.save(i); }
 @Transactional public Incident updateStatus(Long id, IncidentStatus status, String notes){Incident i=one(id); i.setStatus(status);if(notes!=null)i.setResolutionNotes(notes);if(status==IncidentStatus.RESOLVED||status==IncidentStatus.CLOSED)i.setResolvedAt(Instant.now());return repo.save(i);} @Transactional public Incident assign(Long id,Long teamId,Long engineerId){Incident i=one(id);if(teamId!=null)i.setAssignedTeam(teams.findById(teamId).orElseThrow(()->new NoSuchElementException("Team not found")));if(engineerId!=null)i.setAssignedEngineer(engineers.findById(engineerId).orElseThrow(()->new NoSuchElementException("Engineer not found")));i.setStatus(IncidentStatus.ASSIGNED);return repo.save(i);} }
